# Schema reale delle due tabelle storiche (copiato dal database il 2026-10-29): i test girano su questo, non su uno inventato.
CONTACTS_DDL = "CREATE TABLE \"contacts\" (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  company TEXT,\n  role TEXT,\n  type TEXT,\n  country TEXT,\n  city TEXT,\n  email TEXT,\n  official_url TEXT,\n  contact_proof TEXT,\n  verification_level TEXT,\n  fit_reason TEXT,\n  priority TEXT,\n  status TEXT DEFAULT 'to-contact',\n  contacted_at TEXT,\n  reply TEXT,\n  next_action TEXT,\n  next_action_date TEXT,\n  project TEXT DEFAULT 'general',\n  notes TEXT,\n  created_at TEXT DEFAULT (datetime('now')),\n  source_system TEXT DEFAULT 'radar-nas',\n  legacy_id INTEGER\n, enriched_at TEXT, hook_title TEXT, hook_url TEXT, linkedin TEXT, instagram TEXT, social_follow_status TEXT, enrich_attempts INTEGER DEFAULT 0)"
PEOPLE_DDL = "CREATE TABLE people (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  contact_id INTEGER,              -- azienda di appartenenza (contacts.id)\n  name TEXT NOT NULL,\n  role TEXT,\n  email TEXT,\n  email_confidence TEXT,           -- 'verified' | 'guessed-valid' | 'guessed-unverified'\n  linkedin_search TEXT,            -- URL di ricerca LinkedIn (Valerio apre e conferma)\n  instagram_search TEXT,\n  source_url TEXT,                 -- da dove viene (provenienza)\n  social_follow_status TEXT,       -- 'to-follow' | 'followed'\n  created_at TEXT DEFAULT (datetime('now')),\n  UNIQUE(contact_id, name)\n)"
